CREATE OR REPLACE FUNCTION public.user_has_active_access(user_uuid uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    subscription_record RECORD;
    has_access boolean := false;
BEGIN
    -- Get the user's current subscription
    SELECT * INTO subscription_record
    FROM subscriptions 
    WHERE user_id = user_uuid 
    AND status IN ('active', 'cancelled')
    ORDER BY created_at DESC 
    LIMIT 1;

    IF subscription_record IS NULL THEN
        RETURN false;
    END IF;

    -- Check if subscription is active
    IF subscription_record.status = 'active' THEN
        RETURN true;
    END IF;

    -- Check if cancelled subscription is still within access period
    IF subscription_record.status = 'cancelled' THEN
        -- Check grace period first
        IF subscription_record.grace_period_end IS NOT NULL THEN
            RETURN subscription_record.grace_period_end > NOW();
        END IF;

        -- Otherwise check current period end
        RETURN subscription_record.current_period_end > NOW();
    END IF;

    RETURN false;
END;
$function$

CREATE OR REPLACE FUNCTION public._r0_can_user_create_proposal_impl(user_uuid uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
