CREATE OR REPLACE FUNCTION public.protect_subscription_entitlements()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF current_user IN ('postgres', 'supabase_admin', 'service_role') OR public.is_admin() THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'INSERT' THEN
    RAISE EXCEPTION 'Subscriptions are managed by billing.' USING ERRCODE = '42501';
  ELSIF NEW.user_id IS DISTINCT FROM OLD.user_id
     OR NEW.plan IS DISTINCT FROM OLD.plan
     OR NEW.status IS DISTINCT FROM OLD.status
     OR NEW.stripe_customer_id IS DISTINCT FROM OLD.stripe_customer_id
     OR NEW.stripe_subscription_id IS DISTINCT FROM OLD.stripe_subscription_id THEN
    RAISE EXCEPTION 'Subscriptions are managed by billing.' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.r0_assert_self_or_service(target_user uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if target_user is null then raise exception 'user id is required' using errcode='22023'; end if;
  if not (
       current_setting('role', true) = 'service_role'
       or (
         coalesce(current_setting('role', true), 'none') = 'none'
         and session_user in ('service_role','postgres','supabase_admin')
       )
     )
     and auth.uid() is distinct from target_user then
    raise exception 'not authorized for requested user' using errcode='42501';
  end if;
end $function$

CREATE OR REPLACE FUNCTION public.record_first_proposal_funnel_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_attr public.marketing_attribution%rowtype;
begin
  select * into v_attr from public.marketing_attribution where user_id = new.user_id;
  if v_attr.user_id is null then return new; end if;
  insert into public.marketing_funnel_events(event_id, user_id, event_name, attribution, properties, occurred_at)
  values (
    'first_proposal:' || new.user_id::text, new.user_id, 'first_proposal',
    jsonb_build_object('first_touch', v_attr.first_touch, 'last_touch', v_attr.last_touch),
    jsonb_build_object('proposal_id', new.id), coalesce(new.created_at, now())
  ) on conflict (event_id) do nothing;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.record_proposal_funnel_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_attr public.marketing_attribution%rowtype;
  v_prior_proposals bigint;
  v_event_name text;
begin
  select * into v_attr
  from public.marketing_attribution
  where user_id = new.user_id;

  if v_attr.user_id is null then return new; end if;

  select count(*) into v_prior_proposals
  from public.proposals
  where user_id = new.user_id and id <> new.id;

  v_event_name := case
    when v_prior_proposals = 0 then 'first_proposal'
    else 'repeat_proposal'
  end;

  insert into public.marketing_funnel_events(
    event_id, user_id, event_name, attribution, properties, occurred_at
  ) values (
    v_event_name || ':' || new.id::text,
    new.user_id,
    v_event_name,
    jsonb_build_object('first_touch', v_attr.first_touch, 'last_touch', v_attr.last_touch),
    jsonb_build_object('proposal_id', new.id, 'proposal_number', v_prior_proposals + 1),
    coalesce(new.created_at, now())
  ) on conflict (event_id) do nothing;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_tracking_click(token text, clicked_element_type text, clicked_element_text text DEFAULT NULL::text, clicked_element_id text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare target uuid;
begin
  if length(token) < 20 or length(clicked_element_type) > 100 then return false; end if;
  select proposal_id into target
    from public.proposal_tracking
   where tracking_id = token and track_opens;
  if target is null then return false; end if;
  insert into public.proposal_click_tracking (proposal_id, element_type, element_text, element_id)
  values (
    target,
    clicked_element_type,
    left(clicked_element_text, 255),
    left(clicked_element_id, 100)
  );
  return true;
end $function$

