CREATE OR REPLACE FUNCTION public.guard_organization_membership()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare bootstrap_owner boolean; tenant_id uuid; owner_count integer;
begin
  tenant_id := case when tg_op = 'INSERT' then new.organization_id else old.organization_id end;
  perform 1 from public.organizations where id = tenant_id for update;
  bootstrap_owner := tg_op = 'INSERT' and new.role = 'owner'
    and pg_trigger_depth() >= 2
    and exists (select 1 from public.organizations o
                where o.id = new.organization_id and o.created_by = new.user_id)
    and not exists (select 1 from public.organization_memberships m
                    where m.organization_id = new.organization_id);
  if tg_op = 'DELETE'
     and pg_trigger_depth() >= 2
     and current_setting('r2.private_cleanup', true) = old.organization_id::text
     and (select count(*) from public.organization_memberships m
          where m.organization_id = old.organization_id) = 1 then
    return old;
  end if;
  if not bootstrap_owner then
    raise exception 'team memberships are disabled until invitation consent and seat billing ship'
      using errcode = '42501';
  end if;
  if tg_op in ('UPDATE', 'DELETE') and old.role = 'owner'
     and (tg_op = 'DELETE' or new.role <> 'owner') then
    select count(*) into owner_count from public.organization_memberships
    where organization_id = old.organization_id and role = 'owner';
    if owner_count <= 1 then
      raise exception 'organization must retain at least one owner' using errcode = '23514';
    end if;
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end $function$

CREATE OR REPLACE FUNCTION public.guard_organization_owned_record()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare old_data jsonb; new_data jsonb;
begin
  old_data := to_jsonb(old);
  new_data := to_jsonb(new);
  if tg_op = 'UPDATE' and new_data->>'organization_id' is distinct from old_data->>'organization_id' then
    raise exception 'organization ownership cannot be changed in place' using errcode = '42501';
  end if;
  if tg_table_name = 'organizations' and tg_op = 'UPDATE'
     and new_data->>'created_by' is distinct from old_data->>'created_by' then
    raise exception 'organization creator attribution is immutable' using errcode = '42501';
  end if;
  if tg_table_name in ('proposals', 'business_service_profiles', 'company_profiles', 'user_branding_settings') and tg_op = 'UPDATE'
     and new_data->>'user_id' is distinct from old_data->>'user_id' then
    raise exception 'creator attribution cannot be changed in place' using errcode = '42501';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.guard_proposal_catalog_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if TG_OP = 'UPDATE' and old.service_specific_data ? 'catalogJob' then
    if not (coalesce(new.service_specific_data, '{}'::jsonb) ? 'catalogJob') then
      raise exception 'Catalog proposals must retain their versioned job snapshot';
    end if;
    if old.service_specific_data->'catalogJob'->>'catalogVersion' is distinct from
       new.service_specific_data->'catalogJob'->>'catalogVersion' then
      raise exception 'Catalog version changes require a new proposal';
    end if;
  end if;
  if new.service_specific_data ? 'catalogJob' then
    if new.service_type <> 'residential' or
       not exists (select 1 from public.service_catalog_versions where version = new.service_specific_data->'catalogJob'->>'catalogVersion') or
       new.service_specific_data->'catalogJob'->>'catalogVersion' is distinct from new.service_specific_data->'catalogSnapshot'->>'version' then
      raise exception 'Invalid catalog snapshot';
    end if;
  end if;
  return new;
end $function$

